const input = $input.first()?.json ?? {};
const body = input.body ?? input;

return [{
  json: {
    config: {
      companyName: body.companyName || 'ABM Solutions Demo',
      demoMode: body.demoMode !== false
    },
    payload: body
  }
}];

const d = $input.first().json;
const t = d.task;
const text = `${t.title || ''} ${t.description || ''}`.toLowerCase();

let taskType = 'General Operations';
let assignedTeam = 'Operations';

if (/api|integration|sync|webhook|automation|error|bug|technical/.test(text)) {
  taskType = 'Technical Issue';
  assignedTeam = 'Automation Engineering';
} else if (/invoice|billing|payment|refund|charge/.test(text)) {
  taskType = 'Billing and Payments';
  assignedTeam = 'Finance';
} else if (/lead|deal|sales|crm|pipeline|prospect/.test(text)) {
  taskType = 'Sales Operations';
  assignedTeam = 'Revenue Operations';
} else if (/onboarding|customer|account|renewal|cancellation/.test(text)) {
  taskType = 'Customer Success';
  assignedTeam = 'Customer Success';
} else if (/employee|payroll|benefits|hiring|candidate/.test(text)) {
  taskType = 'People Operations';
  assignedTeam = 'Human Resources';
}

let complexity = 'low';

if (
  /multiple systems|data migration|security|compliance|enterprise-wide|architecture/.test(text)
) {
  complexity = 'high';
} else if (
  /integration|api|automation|workflow|configuration|investigation/.test(text)
) {
  complexity = 'medium';
}

const urgency = String(t.urgency || 'medium').toLowerCase();
const customerTier = String(t.customerTier || 'standard').toLowerCase();

let priority = 'P3';

if (
  urgency === 'critical' ||
  (urgency === 'high' && customerTier === 'enterprise')
) {
  priority = 'P1';
} else if (
  urgency === 'high' ||
  complexity === 'high' ||
  customerTier === 'enterprise'
) {
  priority = 'P2';
}

const slaHours = {
  P1: 1,
  P2: 4,
  P3: 24
}[priority];

return [{
  json: {
    ...d,
    result: {
      ...t,
      taskType,
      complexity,
      assignedTeam,
      queue: `${assignedTeam} Queue`,
      priority,
      slaHours,
      routedAt: new Date().toISOString()
    }
  }
}];
